            seo_about_title: "Despre companie | Oțel inox, producție și servicii",
            seo_about_description: "Alex-Lab — ciclu complet pentru oțel inox: debitare, îndoire, sudare, roluire, finisare, producție după desene și comenzi individuale în Chișinău și în toată Moldova.",
            seo_about_h1: "Despre Alex-Lab: precizie, responsabilitate, rezultat",
            seo_about_p1: "Executăm ciclul complet de lucrări cu inox — de la pregătire și debitare până la asamblare și polisare. Inginerii și meșterii noștri livrează calitate industrială constantă.",
            seo_about_p2: "Lucrăm după standarde și fișe tehnologice, stabilim toleranțe, alegem materialul și finisajul, oferim calcul și garanții. Acceptăm comenzi individuale și producție de serie.",
            seo_about_h2: "Ce primiți colaborând cu noi",
            seo_about_li1: "Consultanță profesională și suport în proiectare",
            seo_about_li2: "Termene exacte și devize transparente",
            seo_about_li3: "Controlul calității pe fiecare etapă, rapoarte foto",
            seo_about_li4: "Livrare și montaj în Chișinău",
            seo_about_h3: "Direcții de lucru",
            seo_about_p3: "Realizăm balustrade, cadre, mese și dulapuri, rezervoare, cărucioare, elemente decorative, carcase, hote, coșuri de fum și multe altele.",

            seo_contacts_title: "Contacte | Consultanță și calculul costului dezvoltării",
            seo_contacts_description: "Contactează Alex-Lab: consultanță, calculul costului, dezvoltare de site-uri și aplicații web, suport tehnic și mentenanță. Răspundem rapid prin telefon, e-mail sau formularul de contact.",
            seo_contacts_h1: "Contacte Alex-Lab: mereu în legătură",
            seo_contacts_p1: "Ai nevoie de o estimare sau de o consultație pentru dezvoltarea unui site sau a unei aplicații web? Scrie-ne prin formular sau sună-ne. Trimite descrierea proiectului, exemple de interfață sau cerințele tehnice — vom pregăti oferta, tehnologiile potrivite și termenii de execuție.",
            seo_contacts_h2: "Cum lucrăm",
            seo_contacts_li1: "Analizăm cerințele și alegem tehnologiile potrivite (React, TypeScript, Spring Boot, API, PWA)",
            seo_contacts_li2: "Calculăm costul, stabilim termenele și etapele de dezvoltare",
            seo_contacts_li3: "Dezvoltăm, testăm, publicăm și oferim suport tehnic pentru proiect",
            seo_contacts_h3: "Zona de servicii și consultanță",
            seo_contacts_p2: "Lucrăm online cu clienți din întreaga lume. Pentru companiile din Moldova și România oferim întâlniri și consultații în Chișinău. Oferim garanție pentru lucrări și suport tehnic ulterior.",

            seo_main_title: "Optimizare SEO și promovare pentru aplicații web",
            seo_main_intro: "Nu doar creăm site-uri și aplicații web — le facem vizibile, rapide și prietenoase pentru motoarele de căutare. Fiecare proiect include optimizare SEO și marketing digital pentru a atrage publicul potrivit.",

            seo_standard_title: "Optimizare SEO de bază",
            seo_standard_item1: "Configurarea etichetelor meta (title, description, keywords) pe baza cuvintelor-cheie",
            seo_standard_item2: "Structură clară de URL și sitemap (sitemap.xml, robots.txt)",
            seo_standard_item3: "Optimizarea vitezei de încărcare și a indicatorilor Core Web Vitals",
            seo_standard_item4: "Adăugarea datelor structurate (JSON-LD) pentru motoarele de căutare",
            seo_standard_item5: "Indexare corectă și design responsive pentru toate dispozitivele",
            seo_standard_note: "Aceste servicii sunt incluse în fiecare proiect — site-ul tău va fi pregătit pentru promovare încă de la lansare.",

            seo_custom_title: "SEO avansat și marketing de conținut",
