            guide_grades_p1: "Both grades are austenitic (300 series). The main difference is molybdenum (Mo) in 316, which boosts corrosion resistance, especially in chlorides (sea air, reagents, pools).",
            guide_tbl_head_param: "Parameter",
            guide_tbl_head_304: "AISI 304",
            guide_tbl_head_316: "AISI 316",
            guide_tbl_row_comp: "Cr / Ni / Mo (approx.)",
            guide_tbl_row_comp_304: "≈ 18% Cr, 8–10.5% Ni, no Mo",
            guide_tbl_row_comp_316: "≈ 16–18% Cr, 10–14% Ni, 2–3% Mo",
            guide_tbl_row_corr: "Corrosion resistance",
            guide_tbl_row_corr_304: "Excellent indoors and outdoors away from sea spray",
            guide_tbl_row_corr_316: "Improved resistance to chlorides/salt mist",
            guide_tbl_row_mag: "Magnetism",
            guide_tbl_row_mag_304: "Practically non-magnetic (may become slightly so after forming)",
            guide_tbl_row_mag_316: "Similar",
            guide_tbl_row_food: "Food safety",
            guide_tbl_row_food_304: "Widely used in food equipment",
            guide_tbl_row_food_316: "Also suitable; preferred in aggressive environments",
            guide_tbl_row_price: "Price",
            guide_tbl_row_price_304: "Lower",
            guide_tbl_row_price_316: "Higher (due to Mo)",
            guide_tbl_row_where: "Applications",
            guide_tbl_row_where_304: "Interiors, façades away from sea, kitchens, furniture",
            guide_tbl_row_where_316: "Coast/pools, chemical exposure, sea air, de-icing salts",
            guide_grades_note_title: "In short:",
            guide_grades_note_bul1: "304 — the universal choice for most indoor and many outdoor tasks.",
            guide_grades_note_bul2: "316 — choose where there’s sea, pools, chlorides, or aggressive chemistry.",

            guide_finishes_title: "Surface types and finishing",
            guide_finishes_p1: "Surface affects look, fingerprints visibility, and soil resistance. Below are popular options and typical use. Ra is indicative.",
            guide_fin_2b_title: "2B (mill matte)",
            guide_fin_2b_desc: "Base matte after rolling and pickling.",
            guide_fin_2b_ra: "~0.1–0.2 μm",
            guide_fin_2b_use: "Bending, welding, items for later sanding/painting.",
            guide_fin_ba_title: "BA (bright annealed)",
            guide_fin_ba_desc: "Bright/semi-gloss after recrystallization anneal.",
            guide_fin_ba_ra: "~0.05–0.1 μm",
            guide_fin_ba_use: "Interior décor when a clean reflective look is needed.",
            guide_fin_no4_title: "No.4 / Scotch-Brite (satin)",
            guide_fin_no4_desc: "Unidirectional brushing (typically 180–240 grit).",
            guide_fin_no4_ra: "~0.4–0.8 μm",
            guide_fin_no4_use: "Façades, furniture, railings; good balance of care/looks.",
            guide_fin_hl_title: "Hairline (HL)",
            guide_fin_hl_desc: "Long uniform grain in one direction.",
            guide_fin_hl_ra: "~0.3–0.6 μm",
            guide_fin_hl_use: "Decor panels, doors, furniture fronts.",
            guide_fin_vib_title: "Vibration",
            guide_fin_vib_desc: "Random swirl that hides scratches.",
            guide_fin_vib_ra: "~0.5–1.0 μm",
            guide_fin_vib_use: "High-traffic zones, counters, public spaces.",
            guide_fin_mirror_title: "Mirror No.8",
            guide_fin_mirror_desc: "Mirror polish without visible grain.",
            guide_fin_mirror_ra: "< 0.05 μm",
            guide_fin_mirror_use: "Mirror panels, art; requires more care.",
            guide_fin_bead_title: "Bead-blast",
            guide_fin_bead_desc: "Fine velvety matte texture.",
            guide_fin_bead_ra: "~1.0–2.0 μm",
