            guide_fin_tip: "Care tip: wipe along the grain, use microfiber and neutral agents.",

            guide_care_title: "Care & maintenance",
            guide_care_do: "Do",
            guide_care_do_1: "Wipe regularly with microfiber and mild agent (pH 6–8).",
            guide_care_do_2: "Clean along the grain (for satin/HL/Vibration).",
            guide_care_do_3: "Rinse off salts/chlorides as early as possible.",
            guide_care_do_4: "Passivate (citrate/nitrate) after welding/installation if needed.",
            guide_care_do_5: "Lubricate hardware (hinges, locks) per manufacturer.",
            guide_care_dont: "Avoid",
            guide_care_dont_1: "Bleach and active chlorine; long contact with salt solutions.",
            guide_care_dont_2: "Abrasive carbon-steel pads (rust particles → pitting).",
            guide_care_dont_3: "Prolonged contact with cement/lime without rinsing.",
            guide_care_dont_4: "Cross-contamination in shop: separate tools by material.",
            guide_care_teastain: "Outdoor ‘tea staining’ indicates poor care — regular washing and proper grade (316 near sea) solve it.",

            guide_measure_title: "Typical measuring mistakes",
            guide_meas_rail_title: "Railings / guards",
            guide_meas_rail_1: "Measuring to rough walls — ignoring finish thickness (tile, drywall, plaster).",
            guide_meas_rail_2: "Unaccounted non-parallelism/slope → wrong angles of posts/nodes.",
            guide_meas_rail_3: "No allowance for fasteners: edge setbacks, flange thickness, heads.",
            guide_meas_rail_4: "No installation tolerances: ±3–5 mm and adjustment hardware.",
            guide_meas_top_title: "Countertops / claddings",
            guide_meas_top_1: "Measured before installing appliances/sink → cutouts don’t match.",
            guide_meas_top_2: "No gaps for thermal expansion (~16–17 μm/m·°C).",
            guide_meas_top_3: "Ignoring bend radii and allowances for hem/edge.",
            guide_meas_top_4: "Walls/corners not straight — need a measurement grid.",
            guide_meas_canopy_title: "Canopies / awnings",
            guide_meas_canopy_1: "No data on base bearing capacity and anchor type.",
            guide_meas_canopy_2: "No slopes/drainage, wrong overhangs vs façade.",
            guide_meas_canopy_3: "Ignored expansion joints/gaps in cladding.",
            guide_meas_case_title: "Enclosures / cabinets / covers",
            guide_meas_case_1: "Measured ‘to opening’ without hinges, strikes, seals considered.",
            guide_meas_case_2: "Unplanned cable glands/ventilation and service zones.",
            guide_meas_case_3: "Tight assembly tolerances: no slots/oval holes.",
            guide_meas_check_title: "Pre-measurement checklist:",
