            about_intro1: "We are a team of metalworking specialists who turn your ideas into finished products. Our experience and <b>modern equipment</b> allow us to perform a wide range of tasks — from simple cutting to complex welded structures.",
            about_intro2: "Our company specializes in professional stainless steel and metal structure processing, offering a full cycle of services — from sheet metal cutting to final assembly. We help clients implement both simple projects and complex structures requiring high precision and reliability.",

            about_strengths_title: "Our strengths",
            about_strengths_1: "<b>Modern equipment</b> — we use guillotines, rolling and bending machines, band saws, and welding equipment of the latest generation. This ensures fast, accurate operations with minimal material waste.",
            about_strengths_2: "<b>Wide range of services</b> — cutting, bending, rolling, drilling, welding, finishing, and more. All in one place.",
            about_strengths_3: "<b>Qualified craftsmen</b> — our team of experienced specialists guarantees strength and precision for every detail.",
            about_strengths_4: "<b>Individual approach</b> — we handle both standard and custom projects based on your drawings, sketches, and ideas.",
            about_strengths_5: "<b>Quality</b> — every seam and bend is inspected; products look impeccable both technically and visually.",
            about_strengths_6: "<b>Transparent pricing</b> — clear price list with no hidden fees.",
            about_strengths_7: "<b>On-time delivery</b> — optimized processes allow us to complete orders on schedule.",

            about_services_title: "Our services",
            about_services_1: "<b>Metal cutting</b> — on a guillotine, band saw, or grinder, precisely to your dimensions.",
            about_services_2: "<b>Bending and rolling</b> — we form bends, cylinders, and cones of any complexity.",
            about_services_3: "<b>Drilling and hole cutting</b> — in sheet metal, profile, and round pipes.",
            about_services_4: "<b>Welding</b> — structural, polished, and decorative seams, including spot welding.",
            about_services_5: "<b>Pipe connections fabrication</b> — angle cuts at 90° and 45°.",
            about_services_6: "<b>Finishing</b> — deburring, grinding, polishing, and acid treatment.",
            about_services_7: "<b>On-site measurements</b> — technician visits in Chișinău and beyond.",

            about_clients_title: "Our clients",
            about_clients: "We work with private customers, construction companies, manufacturing enterprises, and the HoReCa sector. We produce both individual elements (countertops, frames, stands) and full structures for projects in Chișinău and across Moldova.",

            about_approach_title: "Our approach",
            about_approach1: "We build long-term relationships with our clients. Each completed project is a showcase of quality and professionalism. Our goal is not just to deliver an order, but to provide a solution that lasts and stands out among competitors.",
            about_approach2: "We value our clients' trust and always strive to deliver the best possible result — whether it's manufacturing structures, parts, or decorative elements.",

            about_why_title: "Why choose us",
            about_why_1: "<b>Precision and quality</b> — we use professional equipment and maintain millimeter-level accuracy.",
            about_why_2: "<b>Comprehensive approach</b> — from material preparation to final welding and polishing.",
            about_why_3: "<b>Custom solutions</b> — we handle both standard and custom-made orders.",
            about_why_4: "<b>Transparent pricing</b> — clear price list for all types of work.",
            about_why_5: "<b>Fast execution</b> — optimized processes ensure on-time delivery.",

