            seo_about_description: "Alex-Lab — full-cycle stainless steel works: cutting, bending, welding, rolling, polishing, and custom projects across Chișinău and Moldova.",
            seo_about_h1: "About Alex-Lab: precision, responsibility, results",
            seo_about_p1: "We perform a complete cycle of stainless-steel works — from preparation and cutting to final assembly and polishing. Our engineers and craftsmen ensure industrial precision and consistent quality.",
            seo_about_p2: "We follow technical standards, approve tolerances, select materials and finishes, provide estimates and warranties. We accept both individual and serial production orders.",
