            seo_about_h3: "Work directions",
            seo_about_p3: "We manufacture railings, frames, tables, tanks, trolleys, decorative elements, housings, hoods, chimneys, and much more.",

            seo_contacts_title: "Contacts | Consultations and project cost estimation",
            seo_contacts_description: "Contact Alex-Lab: consultations, project estimation, website and web app development, technical support and maintenance. We respond quickly via phone, email, or contact form.",
            seo_contacts_h1: "Alex-Lab contacts: always in touch",
            seo_contacts_p1: "Need an estimate or consultation for a website or web app? Write us via the form or call directly. Send your project description, interface examples, or technical specification — we’ll prepare a proposal, technology stack, and timeline.",
